class Solution:
    def countPaths(self, n: int, edges: List[List[int]]) -> int:
        import sys
        sys.setrecursionlimit(400000)
        is_prime = [False] * (n + 1)
        if n >= 2:
            sieve = [True] * (n + 1)
            sieve[0] = sieve[1] = False
            for i in range(2, int(n ** 0.5) + 1):
                if sieve[i]:
                    for j in range(i * i, n + 1, i):
                        sieve[j] = False
            is_prime = sieve
        g = [[] for _ in range(n + 1)]
        for u, v in edges:
            g[u].append(v); g[v].append(u)
        sz = [0] * (n + 1)
        def dfs1(u, p):
            s = 0 if is_prime[u] else 1
            for v in g[u]:
                if v != p:
                    s += dfs1(v, u)
            sz[u] = s
            return s
        dfs1(1, 0)
        self.ans = 0
        def dfs2(u, p, up):
            if is_prime[u]:
                f = up
                for v in g[u]:
                    if v != p:
                        f += sz[v]
                self.ans += f + f * (f - 1) // 2
                down = 0
            else:
                down = up + 1
            for v in g[u]:
                if v != p:
                    dfs2(v, u, down)
        dfs2(1, 0, 0)
        return self.ans

