class Solution {
public:
    long long countPaths(int n, vector<vector<int>>& edges) {
        vector<bool> isp(n + 1, false);
        if (n >= 2) {
            vector<bool> sv(n + 1, true); sv[0] = sv[1] = false;
            for (long long i = 2; i * i <= n; i++)
                if (sv[i]) for (long long j = i * i; j <= n; j += i) sv[j] = false;
            isp = sv;
        }
        vector<vector<int>> g(n + 1);
        for (auto& e : edges) { g[e[0]].push_back(e[1]); g[e[1]].push_back(e[0]); }
        vector<long long> sz(n + 1, 0);
        function<long long(int,int)> dfs1 = [&](int u, int p) -> long long {
            long long s = isp[u] ? 0 : 1;
            for (int v : g[u]) if (v != p) s += dfs1(v, u);
            sz[u] = s; return s;
        };
        dfs1(1, 0);
        long long ans = 0;
        function<void(int,int,long long)> dfs2 = [&](int u, int p, long long up) {
            long long down;
            if (isp[u]) {
                long long f = up;
                for (int v : g[u]) if (v != p) f += sz[v];
                ans += f + f * (f - 1) / 2;
                down = 0;
            } else down = up + 1;
            for (int v : g[u]) if (v != p) dfs2(v, u, down);
        };
        dfs2(1, 0, 0);
        return ans;
    }
};

