class Solution {
    private List<List<Integer>> g;
    private boolean[] isp;
    private long[] sz;
    private long ans;
    public long countPaths(int n, int[][] edges) {
        isp = new boolean[n + 1];
        if (n >= 2) {
            boolean[] sv = new boolean[n + 1];
            Arrays.fill(sv, true); sv[0] = sv[1] = false;
            for (int i = 2; (long) i * i <= n; i++)
                if (sv[i]) for (int j = i * i; j <= n; j += i) sv[j] = false;
            isp = sv;
        }
        g = new ArrayList<>();
        for (int i = 0; i <= n; i++) g.add(new ArrayList<>());
        for (int[] e : edges) { g.get(e[0]).add(e[1]); g.get(e[1]).add(e[0]); }
        sz = new long[n + 1];
        dfs1(1, 0);
        ans = 0;
        dfs2(1, 0, 0L);
        return ans;
    }
    private long dfs1(int u, int p) {
        long s = isp[u] ? 0 : 1;
        for (int v : g.get(u)) if (v != p) s += dfs1(v, u);
        sz[u] = s; return s;
    }
    private void dfs2(int u, int p, long up) {
        long down;
        if (isp[u]) {
            long f = up;
            for (int v : g.get(u)) if (v != p) f += sz[v];
            ans += f + f * (f - 1) / 2;
            down = 0;
        } else down = up + 1;
        for (int v : g.get(u)) if (v != p) dfs2(v, u, down);
    }
}

