var countPaths = function(n, edges) {
    const isp = new Array(n + 1).fill(false);
    if (n >= 2) {
        const sv = new Array(n + 1).fill(true);
        sv[0] = sv[1] = false;
        for (let i = 2; i * i <= n; i++)
            if (sv[i]) for (let j = i * i; j <= n; j += i) sv[j] = false;
        for (let i = 0; i <= n; i++) isp[i] = sv[i];
    }
    const g = Array.from({length: n + 1}, () => []);
    for (const [u, v] of edges) { g[u].push(v); g[v].push(u); }
    const sz = new Array(n + 1).fill(0);
    function dfs1(u, p) {
        let s = isp[u] ? 0 : 1;
        for (const v of g[u]) if (v !== p) s += dfs1(v, u);
        sz[u] = s; return s;
    }
    dfs1(1, 0);
    let ans = 0;
    function dfs2(u, p, up) {
        let down;
        if (isp[u]) {
            let f = up;
            for (const v of g[u]) if (v !== p) f += sz[v];
            ans += f + (f * (f - 1)) / 2;
            down = 0;
        } else down = up + 1;
        for (const v of g[u]) if (v !== p) dfs2(v, u, down);
    }
    dfs2(1, 0, 0);
    return ans;
};
